namespace Sunplus.Agent.UI._MemberInfo.SecurityCode
{
	using System;
	using System.Web.UI;
	using Fanex.Agent.UI._MemberInfo.SecurityCode;
	using Sunplus.Agent.Model.BL.Definitions;
    using Sunplus.Agent.Model.BL.MemberInfo.SecurityCode;

	public partial class ChangeSecurityCode_Page : Fanex.Age.UI.TplPage
	{
		public override void RenderContent(HtmlTextWriter writer)
		{
			this.RegisterJavascriptObject("alertSecCodeEmpty", Resources.Lang.alertSecCodeEmpty);
			this.RegisterJavascriptObject("alertErrorSecCodeConfirm", Resources.Lang.alertErrorSecCodeConfirm);
			this.RegisterJavascriptObject("alertRequiredSecCode", Resources.Lang.lblRequiredSecCode);
			this.RegisterJavascriptObject("alertSecCodeSucc", Resources.Lang.alertSecCodeChangedOK);
			this.RegisterJavascriptObject("alertSecCodeWrongRule", Resources.Lang.lblSecCodeWrongRule);
			this.RegisterJavascriptObject("alertSameSecCode", Resources.Lang.alertSameSecCode);
			this.RegisterJavascriptObject("alertOldSecCodeEmpty", Resources.Lang.alertOldSecCodeEmpty);

			this.RegisterJavascriptObject("custid", Request["custid"]);
			string username = Request["username"];
			this.RegisterJavascriptObject("username", username);

			ChangeSecurityCode_Template tpl = new ChangeSecurityCode_Template();

			string title = Resources.Lang.titleResetSecCode;
			SCResult scResult = CurrentUserSession.SecurityCodeResult;
			if (scResult == SCResult.FORCED_CHANGE_SC_WITHOUT_VALIDATION || scResult == SCResult.FORCED_CHANGE_SC)
			{
				title = Resources.Lang.titleFirstTimeSecCode;
				this.RegisterJavascriptObject("isForcedSecurityCode", true);

				// notice msg
				string noticeMsg = string.Empty;
				if (scResult == SCResult.FORCED_CHANGE_SC)
				{
					noticeMsg += Resources.Lang.alertForcedChangeSCTitle;
				}
				else // FORCED_CHANGE_SC_WITHOUT_VALIDATION
				{
					noticeMsg += Resources.Lang.alertForcedChangeSCWithoutValidationTitle;
				}

				this.RegisterJavascriptObject("forceChangeSecCode", noticeMsg);
				
				// hide password link
				tpl.Password = null;
			}
			else
			{
				this.RegisterJavascriptObject("lblLearnMore", Resources.Lang.lblLearnMore);
				this.RegisterJavascriptObject("language", CurrentUserSession.Language);
			}

			// Reset SC downline, no need show pwd link
			if (!string.IsNullOrEmpty(Request["custid"]))
			{
				// hide password link
				tpl.Password = null;
			}

			// Reset SC sub-account, no need show pwd link
			if (!string.IsNullOrEmpty(Request["subaccid"]))
			{
				this.RegisterJavascriptObject("subaccid", Request["subaccid"]);
				// hide password link
				tpl.Password = null;
			}

            bool alreadyHasSecCode = !string.IsNullOrEmpty(CurrentUserSession.SecurityCode);
            this.RegisterJavascriptObject("alreadyHasSecCode", alreadyHasSecCode);

            if (alreadyHasSecCode 
                && string.IsNullOrEmpty(Request["custid"]) 
                && string.IsNullOrEmpty(Request["subaccid"]))
            {
                SecurityCodeBO bo = new SecurityCodeBO(CurrentUserSession.NetSessionId);
                bo.GenerateSecurityToken();
                this.RegisterJavascriptObject("securityCodeToken", CurrentUserSession.SecurityCodeToken);

                if (CurrentUserSession.IsSubAcc)
                {
                    this.RegisterJavascriptObject("securitySalt", bo.MD5Salt(CurrentUserSession.SubAccId));
                }
                else
                {
                    this.RegisterJavascriptObject("securitySalt", bo.MD5Salt(CurrentUserSession.CustId));
                }
            }
            else
            {
                tpl.OldSecCode.Visible = false;
            }

			// set title
			tpl.title = title + (string.IsNullOrEmpty(username)
				? string.Empty
				: " - " + username);
			writer.Write(tpl);
		}

		public override object InvokeData(System.Collections.Hashtable p)
		{
			return null;
		}

		public override void ProcessRequest(ref System.Collections.Hashtable p)
		{ }

		public override object ValidateRequest(System.Collections.Hashtable p)
		{
			return null;
		}
	}
}